{
  "schema_version": "agentto.spec/v0",
  "name": "Gearbox output bracket",
  "description": "Bracket with a rigid gearbox attachment and a 40 N*m torque about +x, applied as a force couple through two end-face drive lugs. Top and bottom are interpreted along z; depth is y.",
  "units": {
    "length": "mm",
    "force": "N"
  },
  "domain": {
    "kind": "box",
    "size": [160, 80, 80]
  },
  "material": {
    "name": "steel",
    "E": 210000,
    "nu": 0.3
  },
  "volume_fraction": 0.3,
  "supports": [
    {
      "id": "gearbox_attachment",
      "region": {
        "kind": "face",
        "face": "x-"
      },
      "fix": ["x", "y", "z"]
    }
  ],
  "loads": [
    {
      "id": "top_drive_lug",
      "region": {
        "kind": "patch",
        "face": "x+",
        "center": [40, 72],
        "size": [16, 16]
      },
      "force": [0, -625, 0],
      "distribution": "uniform_nodes",
      "note": "Lug occupies z=64..80 mm; the lug centers are 64 mm apart."
    },
    {
      "id": "bottom_drive_lug",
      "region": {
        "kind": "patch",
        "face": "x+",
        "center": [40, 8],
        "size": [16, 16]
      },
      "force": [0, 625, 0],
      "distribution": "uniform_nodes",
      "note": "Lug occupies z=0..16 mm; the force couple produces 40000 N*mm about +x with zero resultant force."
    }
  ],
  "resolution": {
    "h": 2
  }
}
